def validate_registry(registry):
    missing = set(registry) - set(RESULT_SCHEMAS)
    if missing:
        raise RuntimeError("tool output schema missing: " + ", ".join(sorted(missing)))


def project(tokenizer, name, value):
    if name not in RESULT_SCHEMAS:
        return {"privacy_projection": "unregistered output withheld"}
    def walk(obj, field=None, allowed=None):
        if field in SENSITIVE and isinstance(obj, (str, int, float)) and not isinstance(obj, bool):
            return tokenizer._token(SENSITIVE[field], str(obj))
        if isinstance(obj, dict):
            if field in MAPPINGS:
                return {tokenizer._token(MAPPINGS[field], str(k)): walk(v, "label" if field == "known_labels" else None) for k,v in obj.items()}
            fields = allowed if allowed is not None else FIELD_NAMES
            out = {k: walk(v, k, GRAPH_COMPONENT if name == "graph_relations" and k == "components" else None)
                   for k,v in obj.items() if k in fields}
            if obj.get("dimension") in SENSITIVE and "value" in out and isinstance(obj.get("value"), (str, int, float)):
                out["value"] = tokenizer._token(SENSITIVE[obj["dimension"]], str(obj["value"]))
            omitted = len(set(obj) - fields)
            if omitted:
                out["schema_omitted"] = omitted
            return out
        if isinstance(obj, (list, tuple)):
            return [walk(v, field, allowed) for v in obj]
        if isinstance(obj, str):
            if field in PUBLIC_FIELDS and obj in PUBLIC_VALUES:
                return obj
            return tokenizer._token("TEXT", obj)
        if obj is None or isinstance(obj, bool):
            return obj
        if isinstance(obj, (int, float)):
            import math
            if field in PUBLIC_NUMBERS and math.isfinite(obj):
                return obj
            return tokenizer._token("TEXT", str(obj))
        return "[invalid result type withheld]"
    if name == 'search_risk_knowledge' and isinstance(value, dict):
        output = walk(value, allowed=RAG_FIELDS)
        safe_hits = []
        hits = value.get('hits', [])
        for hit in (hits[:10] if isinstance(hits, list) else []):
            if (isinstance(hit, dict) and hit.get('export_policy') == 'public_reference'
                    and hit.get('status') == 'reviewed' and hit.get('simulated') is False):
                # Explicit publication classification, never inferred from contents.
                # tokenize_data still masks recognized/previously-seen identifiers.
                safe_hits.append(tokenizer.tokenize_data({k: v for k, v in hit.items() if k in RAG_FIELDS}))
            else:
                safe_hits.append(walk(hit, allowed=RAG_FIELDS))
        output['hits'] = safe_hits
        if value.get('status') in ('ok', 'no_match'):
            output['status'] = value['status']
        if value.get('mode') in ('bm25', 'bm25+vector'):
            output['mode'] = value['mode']
        return output
    if name == 'get_event_evidence' and isinstance(value, dict):
        from .sdk_projection import project_detection
        output = walk(value, allowed=RESULT_SCHEMAS[name])
        observations = value.get('sdk_observations', [])
        if isinstance(observations, list):
            output['sdk_observations'] = []
            for observation in observations[:10]:
                if not isinstance(observation, dict):
                    continue
                safe = walk(observation)
                safe['sdk_detection'] = project_detection(tokenizer, observation.get('sdk_detection'))
                output['sdk_observations'].append(safe)
        return output
    return walk(value, allowed=GRAPH_TOP if name == "graph_relations" else RESULT_SCHEMAS[name])
